<script>const file=document.getElementById('avatar-file'),preview=document.getElementById('avatar-preview'),race=document.getElementById('race-select'),gender=document.getElementById('gender-select'),face=document.getElementById('face-value'),dialog=document.getElementById('face-dialog');file?.addEventListener('change',()=>{if(file.files[0])preview.src=URL.createObjectURL(file.files[0])});function sync(reset=false){const code=race.selectedOptions[0]?.dataset.code;if(reset){gender.value='';face.value=''}gender.disabled=!race.value;[...gender.options].forEach(o=>o.disabled=(code==='mithra'&&o.value==='male')||(code==='galka'&&o.value==='female'));if(code==='mithra')gender.value='female';if(code==='galka')gender.value='male';document.getElementById('face-open').disabled=!race.value||!gender.value;document.querySelectorAll('.face-option').forEach(b=>b.hidden=b.dataset.race!==race.value||b.dataset.gender!==gender.value)}race.addEventListener('change',()=>sync(true));gender.addEventListener('change',()=>{face.value='';sync()});document.getElementById('face-open').addEventListener('click',()=>{sync();dialog.showModal()});document.getElementById('face-close').addEventListener('click',()=>dialog.close());document.querySelectorAll('.face-option').forEach(b=>b.addEventListener('click',()=>{face.value=b.dataset.id;preview.src=b.querySelector('img').src;dialog.close()}));sync()</script></div></x-layouts::app>
